b5226698-1cab-41a0-8eb2-0b80924223cb	面談	面談内容の登録	{}	[{"id": "it3b2tu6", "path": "b5226698-1cab-41a0-8eb2-0b80924223cb/5e23a54c-74ce-46bc-9529-89578fa40720.png", "marks": [{"h": 0.0669736841718003, "w": 0.056400891012606924, "x": 0.9435991089873931, "y": 0.03670987839087097, "id": "s8rmhyez"}, {"h": 0.05357891790567054, "w": 0.06033741973839006, "x": 0.006781329764444997, "y": 0.2831728418934164, "id": "wvkd1jgy"}]}, {"id": "gdhwbjt7", "path": "b5226698-1cab-41a0-8eb2-0b80924223cb/939ed05d-52aa-4173-930d-930200bcda8a.png", "marks": [{"h": 0.4004129184777994, "w": 0.4689857655568517, "x": 0.2664418610301178, "y": 0.4602246207893775, "id": "hguufjo1"}]}, {"id": "wfg4m9nd", "path": "b5226698-1cab-41a0-8eb2-0b80924223cb/620ab887-0d43-4408-8c73-41f31a14a4f1.png", "marks": [{"h": 0.08629928693858896, "w": 0.45830271509670667, "x": 0.02927822297212206, "y": 0.46517156868707493, "id": "blh0wo4u"}]}, {"id": "lsksp6wt", "path": "b5226698-1cab-41a0-8eb2-0b80924223cb/c45b9f23-bb9c-4525-a7f2-c342cf7dddd1.png", "marks": [{"h": 0.09110423049065276, "w": 0.3333110921993008, "x": 0.008980430032033101, "y": 0.08812162503739478, "id": "9sed4328"}, {"h": 0.05639783049154248, "w": 0.20367896525089824, "x": 0.7963210347491018, "y": 0.18934857869679197, "id": "4royc32k"}]}, {"id": "9s2m5j0t", "path": "b5226698-1cab-41a0-8eb2-0b80924223cb/28e9dc81-0a12-4a34-8af7-bd9b7d6936d0.png", "marks": [{"h": 0.05103574113063161, "w": 0.1292648841600756, "x": 0.4640782798718676, "y": 0.2265267118703889, "id": "wn0up9jm"}, {"h": 0.053409487055729676, "w": 0.3674968301982724, "x": 0.011117045992435197, "y": 0.2253398220992054, "id": "tcr7w142"}, {"h": 0.053409487055729676, "w": 0.11110367783852326, "x": 0.8817854384302618, "y": 0.2253398220992054, "id": "iue046nf"}, {"h": 0.37624020421305143, "w": 0.1399479346202206, "x": 0.01645855655157496, "y": 0.3998108240141102, "id": "kgjyokm5"}]}, {"id": "69gm4rin", "path": "b5226698-1cab-41a0-8eb2-0b80924223cb/8a8c7de1-a8dc-46c1-80db-d79ba3038663.png", "marks": [{"h": 0.3562152142089293, "w": 0.9582694120793888, "x": 0.014321940591172864, "y": 0.17949906422578596, "id": "2s0sh8el"}, {"h": 0.12801487047343935, "w": 0.15490427568490073, "x": 0.8166187983473253, "y": 0.435528754215672, "id": "4742hhp1"}]}, {"id": "p68sh9mh", "path": "b5226698-1cab-41a0-8eb2-0b80924223cb/64f0596f-0798-4f2a-920b-6afd7c836264.png", "marks": [{"h": 0.14784090162415497, "w": 0.3760432940398808, "x": 0.30383255231155804, "y": 0.8369602161774662, "id": "oh2k7xnr"}]}, {"id": "y4hkrvf2", "path": "b5226698-1cab-41a0-8eb2-0b80924223cb/272f6fe6-2aff-4275-a17c-d295cc7ad870.png", "marks": [{"h": 0.14301670869873295, "w": 0.47159360565450326, "x": 0.2903452631115945, "y": 0.31358125903181483, "id": "a1g56o4k"}]}]	[{"id": "022xiumo", "body": "受注担当マイページ画面の右上の面談登録ボタンから面談登録画面に移動します。", "rule": null}, {"id": "owg2v8uu", "body": "TOPメニューの面談登録からも面談登録画面に移動可能です。", "rule": null}, {"id": "fdalcvwt", "body": "LP直案件で案件検索を行い、該当の案件を押下する。もしくは、OC直またはHP経由案件ボタンを押下すると面談シート画面に遷移します。", "rule": "A3パンフレットを入力しながら、より詳細な内容を面談シートに入力してください。面談シートはオーダーシートの基礎となる情報です。また、検討中から戻り受注になった際に面談内容を見返す際にも手書きのメモより詳細に内容が記されているため、思い返し易く、自分以外の人もフォローしやすくなります。"}, {"id": "o0p11rrj", "body": "面談シートは、項目モードと白紙モードの2つのモードがあります。項目モードを選択するとキーボードで入力可能です。白紙モードを押下すると、タブレットペンで手書きでメモを作成可能です。", "rule": null}, {"id": "8akkic35", "body": "テキスト化ボタンを押すと、手書きで書いたメモをAIが読み取り、項目モードのメモ欄にテキスト化された情報が反映されます。", "rule": null}, {"id": "c3npqkrv", "body": "ペンの太さの変更や、蛍光ペンモードの切り替えも可能です。", "rule": null}, {"id": "m79v6v2u", "body": "原本を保存ボタンを押下すると、面談時のメモとして、手書きで書いた画像が案件に保存されます。", "rule": null}, {"id": "cyzdz4z2", "body": "セクションボタンを押下すると、メモを書きたい任意のセクションにすぐに移動可能です。", "rule": null}, {"id": "t5m3ya7n", "body": "白紙モードで手書きしたメモが項目モードの対応するセクションのメモ欄に反映されます。", "rule": null}, {"id": "taldle80", "body": "AIで項目に反映ボタンを押下すると、メモ欄にタイピングしたテキストもしくは、手書きメモから反映させたテキストをAIが分析し、セクションの項目に自動反映します。", "rule": "項目によっては自動反映されなかったり、精度が低くなる可能性があるため人間の目で必ずチェックを行って下さい。"}, {"id": "yr8i7hak", "body": "すべての内容を入力したら、保存して面談結果登録へ進むボタンを押下してください。", "rule": "面談シートを登録すると、案件が作成されます。面談シート入力後は、そのまま面談結果登録をおこなってください。"}, {"id": "lvjgshpm", "body": "ｘｘｘｘｘ", "rule": "ｘｘｘｘ"}, {"id": "87r016gk", "body": "", "rule": null}, {"id": "fh3omjup", "body": "", "rule": null}]	1	\N	2026-08-11 11:53:57.848915+00	2026-08-12 08:27:22.644337+00
\.
